    font-family: var(--font-subtitle-family);
    font-size: var(--gpo-theme-label-size);
    font-weight: var(--font-subtitle-weight);
    line-height: 1.2;
}

.gpo-app .gpo-helptext,
.gpo-app .gpo-ov-helptext,
.gpo-app .gpo-counter {
    color: var(--gpo-theme-muted);
    font-size: var(--gpo-theme-secondary-size);
    line-height: var(--font-body-line-height);
}

.gpo-app .gpo-tooltip {
    color: rgb(var(--color-background));
    background: var(--gpo-theme-text);
    border-radius: var(--gpo-theme-radius);
    font-size: var(--gpo-theme-secondary-size);
}

.gpo-app .gpo-tooltip:after {
    border-color: var(--gpo-theme-text) transparent transparent transparent;
}

.gpo-app .gpo-total,
.gpo-app .gpo-total .money {
    color: var(--gpo-theme-text);
    font-size: var(--gpo-theme-size);
}

/* Button swatches: like .product-form__controls-group input + label */

.gpo-app .gpo-ov-wrapper.horizontal:has(> .gpo-swatches) {
    gap: 1rem;
}

.gpo-app .gpo-swatches.buttons input + label {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2.8rem;
    min-height: 0;
    margin: 0;
    padding: 4px 6px;
    border: 0;
    border-radius: 0;
    color: var(--gpo-theme-muted);
    background: transparent;
    box-shadow: none;
    font-family: var(--font-body-family);
    font-size: var(--gpo-theme-secondary-size);
    font-weight: var(--font-body-weight);
    letter-spacing: normal;
    line-height: var(--font-body-line-height);
    text-transform: none;
    transition: color var(--duration-default);
}

.gpo-app .gpo-swatches.buttons input + label:hover {
    color: var(--gpo-theme-text);
    background: transparent;
}

.gpo-app .gpo-swatches.buttons input:checked + label {
    color: rgb(var(--color-background));
    background: var(--gpo-theme-text);
