.gpo-app .gpo-swatches.buttons input + label span,
.gpo-app .gpo-swatches.buttons .gpo-ov-title,
.gpo-app .gpo-swatches.buttons .gpo-ov-title > span {
    color: inherit;
    font-size: inherit;
    font-weight: inherit;
    line-height: inherit;
}

.gpo-app .gpo-swatches.buttons input:disabled + label {
    color: var(--gpo-theme-muted);
    text-decoration: line-through;
}

/* Color / image: .color-swatch.swatch_size-standard, square with underline */

.gpo-app .gpo-swatches.color-swatches input + label,
.gpo-app .gpo-swatches.image-swatches input + label {
    position: relative;
    display: flex;
    align-items: flex-start;
    width: var(--gpo-theme-swatch-size);
    height: calc(var(--gpo-theme-swatch-size) + 5px);
    min-width: var(--gpo-theme-swatch-size);
    min-height: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

.gpo-app .gpo-swatches.color-swatches .gpo-swatch__inner,
.gpo-app .gpo-swatches.color-swatches .swatch-top,
.gpo-app .gpo-swatches.image-swatches .gpo-swatch__inner,
.gpo-app .gpo-swatches.image-swatches .gpo-swatch__inner .swatch-image {
    border: 0;
    border-radius: 0;
}

/* GPO swatch sizes are inline; keep the native 24px painted square */

.gpo-app .gpo-swatches.color-swatches .gpo-swatch__inner,
.gpo-app .gpo-swatches.image-swatches .gpo-swatch__inner,
.gpo-app .gpo-swatches.color-swatches .swatch-top {
    width: var(--gpo-theme-swatch-size) !important;
    height: var(--gpo-theme-swatch-size) !important;
}

.gpo-app .gpo-swatches.color-swatches .swatch-bottom {
    border-bottom-width: var(--gpo-theme-swatch-size) !important;
    border-left-width: var(--gpo-theme-swatch-size) !important;
}

.gpo-app .gpo-swatches.color-swatches input + label::after,
.gpo-app .gpo-swatches.image-swatches input + label::after {
    content: "";
    position: absolute;
    inset: auto auto 0 0;
    width: 0;
    height: 1px;
    border: 0;
    border-radius: 0;
    background: var(--gpo-theme-muted);
    box-shadow: none;
    opacity: 1;
    transform: none;
    transition: width var(--duration-default);
    pointer-events: none;
}

.gpo-app .gpo-swatches.color-swatches input:checked + label::after,
.gpo-app .gpo-swatches.color-swatches input + label:hover::after,
.gpo-app .gpo-swatches.image-swatches input:checked + label::after,
.gpo-app .gpo-swatches.image-swatches input + label:hover::after {
    width: 100%;
}

.gpo-app .gpo-swatches input:focus-visible + label {
    outline: var(--gpo-theme-focus-outline);
    outline-offset: .2rem;
    box-shadow: var(--gpo-theme-focus-shadow);
}

.gpo-app .gpo-ov-wrapper.vertical .gpo-ov-title,
.gpo-app .gpo-ov-wrapper.vertical .gpo-ov-title > span {
    color: var(--gpo-theme-text);
