/* Choicelist: .field--checkbox; radio adapts the same theme tokens */

.gpo-app .gpo-choicelist input + label {
    padding-left: 2.2rem;
}

.gpo-app .gpo-choicelist input + label,
.gpo-app .gpo-choicelist input + label span,
.gpo-app .gpo-choicelist input:checked + label,
.gpo-app .gpo-choicelist input:checked + label span {
    color: var(--gpo-theme-text);
    font-size: var(--gpo-theme-secondary-size);
    line-height: var(--font-body-line-height);
}

.gpo-app .gpo-choicelist input + label:before,
.gpo-app .gpo-choicelist input:not(:checked) + label:before,
.gpo-app .gpo-choicelist input:checked + label:before {
    width: 1.4rem;
    height: 1.4rem;
    border: .1rem solid rgba(var(--color-foreground), .6);
    border-radius: 50%;
    background: rgb(var(--color-background));
    box-shadow: none;
    transition: border-color var(--duration-default);
}

.gpo-app .gpo-choicelist input + label:hover:before,
.gpo-app .gpo-choicelist input:checked + label:before {
    border-color: var(--gpo-theme-text);
}

.gpo-app .gpo-choicelist input + label:after {
    left: 4px;
    width: 6px;
    height: 6px;
    border: 0;
    border-radius: 50%;
    background: var(--gpo-theme-text);
}

.gpo-app .gpo-choicelist.gpo-checkbox input + label:before {
    border-radius: 0;
}

.gpo-app .gpo-choicelist.gpo-checkbox input:checked + label:before {
    border-color: rgb(var(--color-background));
}

.gpo-app .gpo-choicelist.gpo-checkbox input + label:after {
    content: "";
    left: 3px;
    width: 9px;
    height: 7px;
    border: 0;
    border-radius: 0;
    background: var(--gpo-theme-text);
    -webkit-mask: var(--gpo-theme-check) center/contain no-repeat;
    mask: var(--gpo-theme-check) center/contain no-repeat;
}

/* Dropdown / Select: .product-parameters .select__select / .select-label */

.gpo-app .gpo-select,
.gpo-app .gpo-dropdown .dropdown-button {
    display: flex;
    align-items: center;
    position: relative;
    box-sizing: border-box;
    width: 100%;
    min-height: var(--gpo-theme-select-height);
    border: .1rem solid var(--gpo-theme-input-border);
    border-radius: 0;
    color: rgb(var(--color-foreground-title));
    background: var(--gpo-theme-input-bg);
    box-shadow: none;
    outline: none;
    font-family: var(--font-body-family);
    font-size: 1.2rem;
    font-weight: var(--font-body-weight);
    line-height: normal;
    letter-spacing: normal;
    transition: border var(--duration-default), background-color var(--duration-default);
}

.gpo-app .gpo-select select {
    flex: 1;
    align-self: stretch;
    box-sizing: border-box;
    width: 100%;
    min-height: calc(var(--gpo-theme-select-height) - .2rem);
    margin: 0;
    padding: .9rem 3.2rem .9rem 1.6rem;
    border: 0;
    border-radius: 0;
    background: transparent;
    background-image: none !important;
    appearance: none;
    color: inherit;
    font: inherit;
    cursor: pointer;
}

.gpo-app .gpo-select select:focus,
.gpo-app .gpo-select select:focus-visible {
    outline: none;
    box-shadow: none;
}

.gpo-app .gpo-dropdown .dropdown-button {
    justify-content: flex-start;
    padding: .9rem 3.2rem .9rem 1.6rem;
    cursor: pointer;
}

.gpo-app .gpo-dropdown .dropdown-button__value {
    flex: 1;
    min-width: 0;
}

/* Arrow: .select .icon-caret, rotating with the custom list */

.gpo-app .gpo-select::after,
.gpo-app .gpo-dropdown .dropdown-button::after {
    content: "";
    position: absolute;
    top: calc(50% - 1.2rem);
    right: .8rem;
    width: 2.4rem;
    height: 2.4rem;
    border: 0;
    background: currentColor;
    -webkit-mask: var(--gpo-theme-chevron) center/contain no-repeat;
    mask: var(--gpo-theme-chevron) center/contain no-repeat;
    transform: none;
    transition: transform var(--duration-default);
    pointer-events: none;
}

.gpo-app .gpo-dropdown.expanded .dropdown-button::after {
    transform: rotate(180deg);
}

.gpo-app .gpo-dropdown .dropdown-button__icon {
    display: none !important;
}

/* List: .dropdown-select ul / ul.active; animate only opening (0.2s ease-in) */

.gpo-app .gpo-dropdown .dropdown-list {
    display: block;
    max-height: 0;
    margin: .6rem 0 0;
    padding: 0;
    border-width: 0 1px;
    border-style: solid;
    border-color: var(--gpo-theme-border);
    border-radius: 0;
    background: rgb(var(--color-background));
    box-shadow: none;
    overflow: auto;
    visibility: hidden;
    opacity: 1;
    transform: none;
    transition: none;
    z-index: 11;
}

.gpo-app .gpo-dropdown.expanded .dropdown-list,
.gpo-app .gpo-dropdown.expanded.gpo-image-dropdown .dropdown-list,
.gpo-app .gpo-dropdown.expanded.gpo-color-dropdown .dropdown-list {
    display: block;
    max-height: min(30rem, 50vh);
    padding: .9rem 0;
    border-width: 1px;
    visibility: visible;
    opacity: 1;
    transition: max-height .2s ease-in;
}

.gpo-app .gpo-dropdown .dropdown-list .dropdown-list-wrapper {
    max-height: min(30rem, 50vh);
}

.gpo-app .gpo-dropdown,
.gpo-app .gpo-dropdown .dropdown-suggestion,
.gpo-app .gpo-dropdown input + label {
    color: var(--gpo-theme-text);
    font-size: var(--gpo-theme-secondary-size);
}

.gpo-app .gpo-dropdown .dropdown-item label {
    min-height: 0;
    padding: .8rem 1.6rem;
    margin-bottom: 2px;
    font-family: var(--font-subtitle-family);
    line-height: var(--font-body-line-height);
    transition: background-color var(--duration-default);
}

/* Keep the chosen font previews */

.gpo-app .gpo-font-picker .dropdown-button__value {
    font-family: inherit;
}

.gpo-app .gpo-dropdown .dropdown-suggestion {
    border: 1px solid var(--gpo-theme-input-border);
    border-radius: var(--gpo-theme-radius);
    background: var(--gpo-theme-input-bg);
}

/* Override the base image/color dropdown item height */

.gpo-app .gpo-dropdown .dropdown-item,
.gpo-app .gpo-dropdown .dropdown-item:hover,
.gpo-app .gpo-dropdown.gpo-image-dropdown .dropdown-item,
.gpo-app .gpo-dropdown.gpo-color-dropdown .dropdown-item {
    height: auto;
    min-height: 0;
    line-height: normal;
    background: transparent;
}

.gpo-app .gpo-dropdown input + label:hover,
.gpo-app .gpo-dropdown input:checked + label {
    color: var(--gpo-theme-text);
    background: rgba(var(--color-border), .4);
}

/* Native custom dropdown marks selection with background alone */

.gpo-app .gpo-dropdown input:checked + label::after {
    display: none;
}

/* Input: .field input / textarea source; decorated fields share its painted box */

.gpo-app .gpo-input-wrap,
.gpo-app .gpo-dimension-input-wrap {
    position: relative;
    width: 100%;
    border: 1px solid var(--gpo-theme-input-border) !important;
    border-radius: var(--gpo-theme-radius) !important;
    background-color: var(--gpo-theme-input-bg);
    box-shadow: none;
    overflow: visible;
    transition: border var(--duration-default), background-color var(--duration-default);
}

/* Native fields suppress the pointer-focus outline */

.gpo-app .gpo-input-wrap:focus-within,
.gpo-app .gpo-dimension-input-wrap:focus-within {
    outline: none;
    box-shadow: none;
}

.gpo-app .gpo-input-wrap.gpo-color-box,
.gpo-app .gpo-input-wrap:has(.gpo-phone) {
    overflow: visible;
}

.gpo-app .gpo-input,
.gpo-app .gpo-dimension-input {
    min-width: 0;
    margin: 0;
    padding: 0 1.4rem;
    color: var(--gpo-theme-text) !important;
    font-family: var(--font-body-family);
    font-size: var(--gpo-theme-size);
    font-weight: var(--font-body-weight);
    line-height: var(--font-body-line-height);
    outline: none;
    border: none;
    border-radius: var(--gpo-theme-radius) !important;
    box-shadow: none;
    background-color: transparent;
}

.gpo-app .gpo-input:not(.gpo-textarea),
.gpo-app .gpo-dimension-input:not(.gpo-textarea) {
    height: calc(var(--gpo-theme-input-height) - 2px);
    min-height: 0;
}

.gpo-app .gpo-input::placeholder,
.gpo-app .gpo-dimension-input::placeholder {
    color: rgba(var(--gpo-theme-text-rgb), 0.5);
}

.gpo-app .gpo-input:focus,
.gpo-app .gpo-input:focus-visible,
.gpo-app .gpo-dimension-input:focus,
.gpo-app .gpo-dimension-input:focus-visible {
    border: 0;
    outline: 0 !important;
    box-shadow: none !important;
}

.gpo-app .gpo-input-suffix {
    padding: 0 1.4rem 0 .8rem;
    color: var(--gpo-theme-muted);
    font-size: var(--gpo-theme-size);
}

.gpo-app .gpo-input-prefix {
    padding: 0 0 0 1.4rem;
    color: rgba(var(--gpo-theme-text-rgb), 0.6);
}

.gpo-app .gpo-dropdown .dropdown-button .gpo-input-prefix {
    padding: 0 8px 0 0;
}

.gpo-app .gpo-input-prefix svg {
    fill: currentColor;
}

.gpo-app .gpo-input-prefix svg,
.gpo-app .gpo-input-prefix img {
    width: 16px;
    height: 16px;
}

.gpo-app .gpo-select .gpo-input-prefix + select,
.gpo-app .gpo-input-wrap .gpo-input-prefix + .gpo-input {
    padding-left: 8px;
}

.gpo-app .gpo-dimension-unit {
    color: var(--gpo-theme-text);
    background: transparent;
    border-left: 1px solid var(--gpo-theme-input-border);
    border-radius: 0 !important;
}

.gpo-app .iti {
    min-height: 0;
    border: 0;
    background: transparent;
}

.gpo-app .iti__flag-container {
    padding: 0;
}

.gpo-app .iti--separate-dial-code .iti__selected-flag {
    color: var(--gpo-theme-text);
    background: transparent;
    border-right: 1px solid var(--gpo-theme-input-border);
}

.gpo-app .iti__selected-flag:focus-visible {
    outline: 0 !important;
    box-shadow: none !important;
}

.gpo-app .gpo-color-box .preview-btn {
    z-index: 1;
    margin-left: 1.4rem;
    border-radius: var(--gpo-theme-radius);
}

.gpo-app .gpo-color-box .gpo-color {
    padding-left: 66px;
}

.gpo-app .gpo-textarea {
    height: auto;
    min-height: 10rem;
    padding: 1rem 1.6rem;
    line-height: var(--font-body-line-height);
    resize: vertical;
}

.gpo-app .iti__country-list {
    max-width: min(35rem, calc(100vw - 4rem));
    background: var(--gpo-theme-input-bg);
    color: var(--gpo-theme-text);
}

/* File upload */

.gpo-app .gpo-dropzone {
    border: 1px dashed var(--gpo-theme-input-border) !important;
    border-radius: var(--gpo-theme-radius);
    background-color: var(--gpo-theme-input-bg);
    transition: 0.3s;
}

.gpo-app .gpo-dropzone:hover {
    border-color: var(--gpo-theme-text) !important;
    background-color: var(--gpo-theme-input-bg);
}

.gpo-app .gpo-dropzone__input {
    box-shadow: none;
}

/* Action: .button--primary colors and typography; CSS overlay adapts its animation */

.gpo-app .gpo-dropzone__action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 3.6rem;
    position: relative;
    overflow: hidden;
    isolation: isolate;
    padding: 1rem 1.3rem;
    border: 1px solid transparent;
    border-radius: var(--border-radius-button);
    color: rgb(var(--color-button-text));
    background: rgb(var(--color-button));
    box-shadow: none;
    font-family: var(--font-button-family);
    font-size: calc(var(--font-button-scale) * 1rem);
    font-weight: var(--font-button-weight);
    letter-spacing: calc(var(--font-button-letter-spacing) * .1);
    line-height: 1.2;
    text-transform: var(--font-button-text-transform);
    transition: color .1s linear, border var(--duration-default);
}

.gpo-app .gpo-dropzone:hover .gpo-dropzone__action {
    color: rgb(var(--color-button-text-hover));
    border-color: rgb(var(--color-button-border-hover));
}

.gpo-app .gpo-dropzone__action::before {
    content: "";
    position: absolute;
    inset: 0 0 -5% -70%;
    width: 171%;
    height: 122%;
    z-index: -1;
    background: rgb(var(--color-button-hover));
    transform: translateY(160%) rotate(20deg);
    transition: transform .3s ease-out;
}

.gpo-app .gpo-dropzone:hover .gpo-dropzone__action::before {
    transform: none;
}

.gpo-app .gpo-dropzone__caption {
    color: rgba(var(--color-foreground), 0.65);
    font-size: var(--gpo-theme-secondary-size);
}

.gpo-app .gpo-f-card,
.gpo-app .gpo-uploading {
    margin-top: 8px;
    border: 1px solid var(--gpo-theme-input-border);
    border-radius: var(--gpo-theme-radius);
    color: var(--gpo-theme-text);
    background: var(--gpo-theme-input-bg);
    padding: 10px 12px;
}

.gpo-app .gpo-f-link {
    color: var(--gpo-theme-text);
}

.gpo-app .gpo-f-name {
    color: var(--gpo-theme-text);
    font-size: var(--gpo-theme-size);
    word-break: break-all;
}

/* Remove: like .button--secondary */

.gpo-app .gpo-f-rm {
    border: 1px solid rgb(var(--color-button-secondary-text));
    border-radius: var(--border-radius-button);
    color: rgb(var(--color-button-secondary-text));
    background: transparent;
    box-shadow: none;
    transition: var(--duration-default);
}

.gpo-app .gpo-f-rm:hover {
    color: rgb(var(--color-button-text-hover));
    background: rgb(var(--color-button-hover));
    border-color: rgb(var(--color-button-hover));
}

.gpo-app .gpo-uploading span {
    margin-left: 28px;
    color: var(--gpo-theme-text);
    font-size: var(--gpo-theme-size);
    font-weight: var(--font-body-weight);
}

.gpo-app .gpo-uploading::after {
    left: 12px;
    width: 16px;
    height: 16px;
    border-width: 2px;
    border-color: var(--gpo-theme-text) var(--gpo-theme-text) var(--gpo-theme-text) transparent;
}

/* Switch: theme foreground/background token adaptation */

.gpo-app .gpo-switch {
    display: block;
}

.gpo-app .gpo-switch input + label,
.gpo-app .gpo-switch input + label span {
    color: var(--gpo-theme-text);
    font-size: var(--gpo-theme-size);
}

.gpo-app .gpo-switch input + label:before {
    background: var(--gpo-theme-border);
}

.gpo-app .gpo-switch input:checked + label:before {
    background: var(--gpo-theme-text);
}

.gpo-app .gpo-switch input + label:after {
    background: var(--gpo-theme-input-bg);
}

/* Range: theme foreground/input-border token adaptation */

.gpo-app .gpo-range-tooltip {
    color: var(--gpo-theme-input-bg);
    background-color: var(--gpo-theme-text);
    border-radius: var(--gpo-theme-radius);
    font-size: var(--gpo-theme-secondary-size);
}

.gpo-app .gpo-range-tooltip::after {
    border-color: var(--gpo-theme-text) transparent transparent transparent;
}

.gpo-app .gpo-range-min,
.gpo-app .gpo-range-max {
    color: rgba(var(--gpo-theme-text-rgb), 0.75);
    font-size: var(--gpo-theme-secondary-size);
}

.gpo-app .gpo-range .gpo-range-input {
    height: auto;
    margin: 0;
    padding: 0;
    border: 0;
    box-shadow: none;
    background: transparent;
}

.gpo-app .gpo-range .gpo-range-input::-webkit-slider-runnable-track {
    background: linear-gradient(to right, var(--gpo-theme-text) var(--progress), var(--gpo-theme-border) var(--progress));
}

.gpo-app .gpo-range .gpo-range-input::-moz-range-track {
    background: var(--gpo-theme-input-border);
}

.gpo-app .gpo-range .gpo-range-input::-moz-range-progress {
    background-color: var(--gpo-theme-text);
}

.gpo-app .gpo-range .gpo-range-input::-webkit-slider-thumb {
    background-color: var(--gpo-theme-text);
}

.gpo-app .gpo-range .gpo-range-input::-moz-range-thumb {
    background-color: var(--gpo-theme-text);
}

/* Tabs: theme-token adaptation for horizontal tabs */

.gpo-app .gpo-tabs .gpo-tabs-tabpanel .gpo-tabs-tabcontent {
    color: var(--gpo-theme-text);
    font-size: var(--gpo-theme-size);
    line-height: var(--font-body-line-height);
    border: 0;
    background: transparent;
}

/* Horizontal: adapt the native size-pill selection */

.gpo-app .gpo-tabs:not(.gpo-tabs-vertical) .gpo-tabs-title .gpo-tabs-tab {
    margin: 0 1rem 5px 0;
    padding: 4px 6px;
    border: 0;
    border-radius: 0;
    color: var(--gpo-theme-muted);
    background: transparent;
    box-shadow: none;
    font-family: var(--font-body-family);
    font-size: var(--gpo-theme-secondary-size);
    font-weight: var(--font-body-weight);
    line-height: var(--font-body-line-height);
    transition: color var(--duration-default);
}

.gpo-app .gpo-tabs:not(.gpo-tabs-vertical) .gpo-tabs-title .gpo-tabs-tab:hover {
    color: var(--gpo-theme-text);
}

.gpo-app .gpo-tabs:not(.gpo-tabs-vertical) .gpo-tabs-title .gpo-tabs-tab.gpo-tab-active {
    color: rgb(var(--color-background));
    background: var(--gpo-theme-text);
}

.gpo-app .gpo-tabs:not(.gpo-tabs-vertical) .gpo-tabs-tabpanel .gpo-tabs-tabcontent {
    padding: 1.2rem 0 0;
}

/* Vertical: like .about__accordion-toggle / .subtitle */

.gpo-app .gpo-tabs.gpo-tabs-vertical {
    border: 0;
    border-radius: 0;
    background: transparent;
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab,
.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab.gpo-tab-active {
    flex-direction: row;
    justify-content: space-between;
    margin: 0;
    padding: 1.2rem 0;
    border: 0;
    border-top: .1rem solid var(--gpo-theme-border);
    border-radius: 0;
    color: var(--gpo-theme-text);
    background: transparent;
    font-family: var(--font-subtitle-family);
    font-size: var(--gpo-theme-label-size);
    font-weight: var(--font-subtitle-weight);
    line-height: 1.2;
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab::before {
    display: none;
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab::after {
    content: "";
    width: 2rem;
    height: 2rem;
    margin-left: 1rem;
    background: currentColor;
    -webkit-mask: var(--gpo-theme-chevron) center/contain no-repeat;
    mask: var(--gpo-theme-chevron) center/contain no-repeat;
    transition: transform var(--duration-default);
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-title .gpo-tabs-tab.gpo-tab-active::after {
    transform: rotate(180deg);
}

.gpo-app .gpo-tabs.gpo-tabs-vertical .gpo-tabs-tabpanel .gpo-tabs-tabcontent {
    margin: 0;
    padding: 0 0 1.2rem;
    background: transparent;
}

